while (bit_index < binfo->size) {
    size_t word_idx = bit_index / (sizeof(uint64_t) * 8);
    size_t bit_offset = bit_index % (sizeof(uint64_t) * 8);
    uint64_t *word_ptr = reinterpret_cast<uint64_t*>(bitmap) + word_idx;

    uint64_t current_val = *word_ptr;
    if (current_val == ~0ULL) {
        bit_index += (sizeof(uint64_t) * 8) - bit_offset;
        continue;
    }

    for (size_t i = bit_offset; i < sizeof(uint64_t) * 8; ++i) {
        if (!(current_val & (1ULL << i))) {
            uint64_t mask = (1ULL << i);
            uint64_t old_val = *word_ptr;
            if (std::atomic_ref<uint64_t>(*word_ptr).compare_exchange_strong(old_val, old_val | mask)) {
                return word_idx * (sizeof(uint64_t) * 8) + i;
            }
            current_val = old_val;
            i--; // Retry this bit with updated value
        }
    }
    bit_index += (sizeof(uint64_t) * 8) - bit_offset;
}
return std::numeric_limits<size_t>::max();
